describe('Modal Dialog', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL where the modal can be triggered
        cy.get('.open-modal-button').click(); // Replace with the actual selector to open the modal
    });

    it('should close the modal when the Escape key is pressed', () => {
        cy.get('.modal').should('be.visible'); // Ensure the modal is visible
        cy.get('body').type('{esc}'); // Simulate pressing the Escape key
        cy.get('.modal').should('not.exist'); // Verify the modal is closed
    });

    it('should not close the modal when clicking outside of it', () => {
        cy.get('.modal').should('be.visible'); // Ensure the modal is visible
        cy.get('.modal-background').click(); // Replace with the actual selector for the area outside the modal
        cy.get('.modal').should('be.visible'); // Verify the modal is still open
    });
});
